with enriched as (select id, customer_id, account_type, balance, opened_date, status, percent_rank() over (order by balance nulls last) as balance_percent_rank, percent_rank() over (partition by account_type order by balance desc nulls last) as balance_percent_rank_2, avg(balance) over (order by opened_date, id rows between 6 preceding and 1 preceding) as balance_avg_6_prior from accounts) select s.id, s.customer_id, s.opened_date, s.balance_percent_rank, s.balance_percent_rank_2, (select avg(x.monthly_fee) from subscriptions x where x.customer_id = s.customer_id) as avg_subscription_monthly_fee from enriched s order by balance_percent_rank_2 nulls last, id limit 20;
